pub fn read_setpoint(dev: &Device) -> Result<f64, Box<dyn Error>> {
    let raw = dev.read_register(0x1F)?;
    let text = std::str::from_utf8(&raw)?;
    Ok(text.trim().parse::<f64>()? * SCALE)
}

pub fn poll_loop(port: &mut Port, tx: Sender<Reading>) {
    loop {
        let frame = port.read_frame().unwrap();
        let reading = decode(&frame).unwrap();
        tx.send(reading).unwrap();
    }
}

fn apply(&mut self, samples: &Vec<Sample>) {
    for s in samples.clone() {
        self.buffer.push(s.clone());
    }
    self.recompute(self.buffer.clone());
}
